func makeMiddleware(ch chan string, name string) func(http.Handler) http.Handler {
	return func(h http.Handler) http.Handler {
		fn := func(w http.ResponseWriter, r *http.Request) {
			ch <- "before " + name
			h.ServeHTTP(w, r)
			ch <- "after " + name
		}
		return http.HandlerFunc(fn)
	}

